const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Pantanal region (approximate boundary)
  const pantanal = ee.Geometry.Polygon([
    [[-58.5, -22.0], [-58.5, -16.0], [-55.0, -16.0], [-55.0, -22.0], [-58.5, -22.0]]
  ]);

  // 2. Load MODIS fire detection data
  const fireCollection = ee.ImageCollection('MODIS/006/MCD14ML');

  // 3. Get fire count for June 11, 2024
  const target_date = '2024-06-11';
  const fires_2024 = fireCollection
    .filterDate(target_date, ee.Date(target_date).advance(1, 'day'))
    .filterBounds(pantanal);

  const size_2024 = fires_2024.size().getInfo();
  console.log(`Images on ${target_date}: ${size_2024}`);

  if (size_2024 === 0) {
    console.log('No fire data available for June 11, 2024');
    console.log('<answer>C1</answer>');
    return;
  }

  // Count fire detections in 2024
  const fire_count_2024 = fires_2024.size().getInfo();
  console.log(`Fire detections on June 11, 2024: ${fire_count_2024}`);

  // 4. Get historical June fire counts (2000-2023)
  const years = [];
  for (let year = 2000; year <= 2023; year++) {
    years.push(year);
  }

  let max_historical = 0;
  let max_year = 0;
  let max_date = '';

  for (const year of years) {
    const june_start = `${year}-06-01`;
    const june_end = `${year}-07-01`;

    const june_fires = fireCollection
      .filterDate(june_start, june_end)
      .filterBounds(pantanal);

    const daily_counts = [];
    for (let day = 1; day <= 30; day++) {
      const date_str = `${year}-06-${String(day).padStart(2, '0')}`;
      const day_fires = fireCollection
        .filterDate(date_str, ee.Date(date_str).advance(1, 'day'))
        .filterBounds(pantanal);

      const count = day_fires.size().getInfo();
      daily_counts.push(count);

      if (count > max_historical) {
        max_historical = count;
        max_year = year;
        max_date = date_str;
      }
    }
  }

  console.log(`Maximum historical June detections: ${max_historical} on ${max_date}`);
  console.log(`2024 detections: ${fire_count_2024}`);

  // 5. Compare and determine answer
  if (fire_count_2024 === null || fire_count_2024 === undefined) {
    console.log('Calculation failed - invalid result');
    console.log('<answer>C3</answer>');
  } else if (fire_count_2024 > max_historical) {
    console.log('2024 fire count exceeds historical maximum');
    console.log('<answer>A</answer>');
  } else {
    console.log('2024 fire count does not exceed historical maximum');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
